constexpr int tracks=8, steps=128, slots=48, rate=48000;
const char* pitches[]={"C","C#","D","EB","E","F","F#","G","AB","A","BB","B"};
const char* factory[]={"KICK","HAT","SINE BASS","KEYS","HARMONIC","SAW","SQUARE","FM","SNARE","OMONDEU"};
const char* effects[]={"OFF","GATE","RETRIG","DRIVE","REVERB","DELAY","SLICER","SLICE","EQ"};
int clamp(int v,int a,int b){return std::clamp(v,a,b);}
std::string noteName(int n){return std::string(pitches[n%12])+std::to_string(n/12-1);}
std::string num(int n,int width=2){char b[32];snprintf(b,sizeof b,"%0*d",width,n);return b;}
uint64_t pack(const std::vector<int>& ns){uint64_t v=0;for(size_t i=0;i<std::min<size_t>(8,ns.size());i++)v|=uint64_t(ns[i]+1)<<(i*8);return v;}
struct Cell{std::vector<int> notes;int instrument=-1,velocity=100,volume=100,pan=0,fx=0,fxv=50,fx2=0,fxv2=50,micro=0,duration=0;bool off=false;std::array<int,4> eq{},eq2{};bool empty()const{return notes.empty()&&!off&&instrument<0&&fx==0&&fx2==0&&velocity==100&&volume==100&&pan==0&&micro==0;}};
struct Pattern{int length=64;std::string name;std::array<std::array<Cell,steps>,tracks> cells;std::array<int,tracks> instruments,levels;std::array<std::array<int,3>,tracks> sends{};std::array<std::array<int,4>,tracks> eq{};int mute=0,solo=0;Pattern(){instruments.fill(-1);levels.fill(100);}};
struct Slot{std::string name="EMPTY";int wave=0,root=60,mode=0,start=0,end=0,position=500,length=120,shape=3,direction=0,spread=8,octave=0;double sampleRate=rate;std::vector<float> pcm;std::vector<int> slices;int lfoMode=0,lfoShape=0,lfoSpeed=0,lfoFree=25,lfoDepth=100,scanMode=0;std::array<int,5> anchors{0,250,500,750,1000};std::array<int,23> patch=omondeu::defaults;};
struct Project{std::map<int,Pattern> patterns{{0,Pattern{}}};std::array<Slot,slots> instruments;std::vector<int> song{0};int selected=0,bpm=1200,advance=1,master=100;std::array<int,11> fx{50,10,0,76,100,55,3,43,65,70,1};Project(){for(int i=0;i<10;i++){instruments[i].name=factory[i];instruments[i].wave=i;}}};
Project project;
std::array<unsigned,slots> sampleRevision{};
Pattern& pat(){return project.patterns[project.selected];}
void publishCell(int p,int t,int s){const auto &c=project.patterns.at(p).cells[t][s];int ins=c.instrument>=0?c.instrument:project.patterns.at(p).instruments[t];if(c.empty())ins=-1;tm_cell_at4(p,t,s,c.off?UINT64_MAX:pack(c.notes),ins,c.velocity,c.volume,c.pan,c.fx==8?0:c.fx,c.fxv,c.fx2==8?0:c.fx2,c.fxv2,c.micro,c.duration);std::array<int,4> e{};for(int i=0;i<4;i++)e[i]=clamp(c.eq[i]+c.eq2[i],-18,18);tm_step_eq(p,t,s,e[0],e[1],e[2],e[3]);}
const int lfoRates[]={24576,18432,12288,9216,6144,4608,3072,2304,1536,1152,768,576,384,288,192,144,96,72,64,48,36,32,24,16,12,8,6,4,3};
void publishSampleConfig(int i){auto &s=project.instruments[i];tm_sample_config_scan(i,s.mode,s.start,s.end,s.slices.data(),s.slices.size(),s.position,s.length,s.shape,s.direction,s.spread,s.lfoMode,s.lfoShape,s.lfoMode==2?s.lfoFree:lfoRates[clamp(s.lfoSpeed,0,28)],s.lfoDepth,s.scanMode,s.anchors.data());tm_sample_octave(i,s.octave);}
void publishSlot(int i){++sampleRevision[i];auto &s=project.instruments[i];tm_instrument_wave(i,s.wave);tm_omondeu(i,s.patch.data());if(s.pcm.empty())tm_instrument_clear(i);else{tm_instrument_sample(i,s.pcm.data(),s.pcm.size(),s.sampleRate,s.root);publishSampleConfig(i);}}
void publishMix(int i){auto &p=project.patterns[i];int mask=p.solo?((1<<tracks)-1)&~p.solo:p.mute;tm_pattern_mute_mask(i,mask|0xffff00);for(int t=0;t<tracks;t++){tm_pattern_track_volume(i,t,p.levels[t]);auto &s=p.sends[t];tm_track_sends(i,t,s[0],s[1],s[2]);auto &e=p.eq[t];tm_track_eq(i,t,e[0],e[1],e[2],e[3]);}}
void publishFX(){auto &f=project.fx;tm_fx_settings(f[0],f[1],f[2],f[3],f[4],f[5],f[6],f[7],f[8],f[9],f[10]);}
void publishSong(){for(int n=0;n<(int)project.song.size();n++){auto i=project.song[n];tm_song_set(n,i,project.patterns[i].length);}tm_song_count(project.song.size());}
void publishAll(){for(int i=0;i<slots;i++)publishSlot(i);for(auto &[i,p]:project.patterns){publishMix(i);for(int t=0;t<tracks;t++)for(int s=0;s<steps;s++)publishCell(i,t,s);}for(int t=tracks;t<24;t++)tm_mute(t,1);tm_master(project.master);tm_bpm_tenths(project.bpm);tm_select_pattern(project.selected,pat().length);publishSong();publishFX();tm_dynamics(0,1,1,-24,3,5,150,0,-30,6);}

// Compact standard JSON matching the desktop's Codable project shape.
using JSON=std::unique_ptr<cJSON,decltype(&cJSON_Delete)>;
JSON json(cJSON* p){return JSON(p,cJSON_Delete);}
cJSON* item(cJSON* p,const char* key){return cJSON_GetObjectItemCaseSensitive(p,key);}
int val(cJSON* p,const char* key,int def,int lo,int hi){auto v=item(p,key);return cJSON_IsNumber(v)?clamp(v->valueint,lo,hi):def;}
std::string str(cJSON* p,const char* key,const char* def=""){auto v=item(p,key);return cJSON_IsString(v)?v->valuestring:def;}
void add(cJSON* p,const char* key,int v){cJSON_AddNumberToObject(p,key,v);}
template<class A> cJSON* arr(const A& a){auto r=cJSON_CreateArray();for(auto v:a)cJSON_AddItemToArray(r,cJSON_CreateNumber(v));return r;}
template<class A> void readarr(cJSON* p,A& a,int lo,int hi){int i=0;for(auto &v:a){auto x=cJSON_GetArrayItem(p,i++);if(cJSON_IsNumber(x))v=clamp(x->valueint,lo,hi);}}
const char b64[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
std::string encode(const std::vector<float>& v){const auto *p=reinterpret_cast<const unsigned char*>(v.data());size_t n=v.size()*4;std::string o;o.reserve((n+2)/3*4);for(size_t i=0;i<n;i+=3){uint32_t x=uint32_t(p[i])<<16;if(i+1<n)x|=uint32_t(p[i+1])<<8;if(i+2<n)x|=p[i+2];o+=b64[(x>>18)&63];o+=b64[(x>>12)&63];o+=i+1<n?b64[(x>>6)&63]:'=';o+=i+2<n?b64[x&63]:'=';}return o;}
bool decode(const std::string& s,std::vector<float>& v){if(s.size()>5333340)return false;std::vector<unsigned char> b;b.reserve(s.size()*3/4);uint32_t a=0;int bits=0;for(char c:s){if(c=='=')break;auto p=std::strchr(b64,c);if(!p)return false;a=(a<<6)|uint32_t(p-b64);bits+=6;if(bits>=8){bits-=8;b.push_back((a>>bits)&255);}}if(b.empty()||b.size()%4)return false;v.resize(b.size()/4);std::memcpy(v.data(),b.data(),b.size());for(float &x:v)if(!std::isfinite(x))x=0;return true;}
cJSON* writeCell(const Cell& c){auto o=cJSON_CreateObject();cJSON_AddItemToObject(o,"notes",arr(c.notes));std::string label=c.notes.size()>1?noteName(c.notes.front())+" CHORD":"";cJSON_AddStringToObject(o,"label",label.c_str());if(c.empty())return o;if(c.instrument>=0)add(o,"instrument",c.instrument);add(o,"velocity",c.velocity);add(o,"volume",c.volume);add(o,"pan",c.pan);if(c.fx){add(o,"fx",c.fx);add(o,"fxValue",c.fxv);if(c.fx==8)cJSON_AddItemToObject(o,"eq1",arr(c.eq));}if(c.fx2){add(o,"fx2",c.fx2);add(o,"fx2Value",c.fxv2);if(c.fx2==8)cJSON_AddItemToObject(o,"eq2",arr(c.eq2));}if(c.micro)add(o,"micro",c.micro);if(c.duration)add(o,"duration",c.duration);if(c.off)cJSON_AddBoolToObject(o,"noteOff",1);return o;}
Cell readCell(cJSON* o){Cell c;auto ns=item(o,"notes");for(int i=0;i<std::min(8,cJSON_GetArraySize(ns));i++){auto n=cJSON_GetArrayItem(ns,i);if(cJSON_IsNumber(n))c.notes.push_back(clamp(n->valueint,0,127));}c.instrument=val(o,"instrument",-1,-1,47);c.velocity=val(o,"velocity",100,0,100);c.volume=val(o,"volume",100,0,100);c.pan=val(o,"pan",0,-50,50);c.fx=val(o,"fx",0,0,8);c.fxv=val(o,"fxValue",50,0,100);c.fx2=val(o,"fx2",0,0,8);c.fxv2=val(o,"fx2Value",50,0,100);c.micro=val(o,"micro",0,0,99);c.duration=val(o,"duration",0,0,511);c.off=cJSON_IsTrue(item(o,"noteOff"));readarr(item(o,"eq1"),c.eq,-18,18);readarr(item(o,"eq2"),c.eq2,-18,18);return c;}
bool save(const fs::path& path){auto root=json(cJSON_CreateObject());auto r=root.get();auto pats=cJSON_AddObjectToObject(r,"patterns");for(auto &[id,p]:project.patterns){auto o=cJSON_AddObjectToObject(pats,std::to_string(id).c_str());add(o,"length",p.length);cJSON_AddStringToObject(o,"name",p.name.c_str());cJSON_AddBoolToObject(o,"expanded",0);auto cells=cJSON_AddArrayToObject(o,"cells");for(int t=0;t<24;t++){auto a=cJSON_CreateArray();cJSON_AddItemToArray(cells,a);for(int s=0;s<steps;s++)cJSON_AddItemToArray(a,writeCell(t<tracks?p.cells[t][s]:Cell{}));}std::array<int,24> ins,levels;ins.fill(-1);levels.fill(100);std::copy(p.instruments.begin(),p.instruments.end(),ins.begin());std::copy(p.levels.begin(),p.levels.end(),levels.begin());cJSON_AddItemToObject(o,"trackInstruments",arr(ins));cJSON_AddItemToObject(o,"trackVolumes",arr(levels));auto sends=cJSON_AddArrayToObject(o,"sends");auto eq=cJSON_AddArrayToObject(o,"trackEQ");for(int t=0;t<24;t++){cJSON_AddItemToArray(sends,arr(t<tracks?p.sends[t]:std::array<int,3>{}));cJSON_AddItemToArray(eq,arr(t<tracks?p.eq[t]:std::array<int,4>{}));}auto m=cJSON_AddArrayToObject(o,"trackMutes"),so=cJSON_AddArrayToObject(o,"trackSolos");for(int t=0;t<tracks;t++){if(p.mute&(1<<t))cJSON_AddItemToArray(m,cJSON_CreateNumber(t));if(p.solo&(1<<t))cJSON_AddItemToArray(so,cJSON_CreateNumber(t));}}
    cJSON_AddNumberToObject(r,"bpm",project.bpm/10.0);add(r,"selected",project.selected);add(r,"step",project.advance);add(r,"master",project.master);cJSON_AddItemToObject(r,"song",arr(project.song));auto sa=cJSON_AddArrayToObject(r,"slots");for(auto &s:project.instruments){auto o=cJSON_CreateObject();cJSON_AddItemToArray(sa,o);cJSON_AddStringToObject(o,"name",s.name.c_str());add(o,"wave",s.wave);add(o,"root",s.root);if(s.wave==9){auto p=cJSON_AddObjectToObject(o,"omondeu");cJSON_AddItemToObject(p,"values",arr(s.patch));}if(!s.pcm.empty()){cJSON_AddStringToObject(o,"pcm",encode(s.pcm).c_str());cJSON_AddNumberToObject(o,"sampleRate",s.sampleRate);auto p=cJSON_AddObjectToObject(o,"playback");add(p,"mode",s.mode);add(p,"start",s.start);add(p,"end",s.end);add(p,"position",s.position);add(p,"grainLength",s.length);add(p,"shape",s.shape);add(p,"direction",s.direction);add(p,"spread",s.spread);add(p,"octave",s.octave);cJSON_AddItemToObject(p,"slices",arr(s.slices));if(s.lfoMode){auto a=cJSON_AddObjectToObject(p,"positionAutomation");add(a,"mode",s.lfoMode);add(a,"shape",s.lfoShape);add(a,"speed",s.lfoSpeed);add(a,"freeRate",s.lfoFree);add(a,"depth",s.lfoDepth);add(a,"scanMode",s.scanMode);cJSON_AddItemToObject(a,"anchors",arr(s.anchors));}}}
    auto fx=cJSON_AddObjectToObject(r,"fxSettings");const char* keys[]={"size","decay","predelay","damping","width","reverbLevel","division","feedback","delayDamping","delayLevel"};add(fx,"preset",5);for(int i=0;i<10;i++)add(fx,keys[i],project.fx[i]);cJSON_AddBoolToObject(fx,"pingpong",project.fx[10]);char* data=cJSON_PrintUnformatted(r);if(!data)return false;std::ofstream f(path.string()+".tmp",std::ios::binary);f<<data;cJSON_free(data);f.close();if(!f)return false;std::error_code e;fs::rename(path.string()+".tmp",path,e);return !e;}
bool load(const fs::path& path,std::string& error){if(!fs::exists(path)||fs::file_size(path)>100000000){error="PROJECT MISSING OR TOO LARGE";return false;}std::ifstream f(path,std::ios::binary);std::string data((std::istreambuf_iterator<char>(f)),{});auto root=json(cJSON_Parse(data.c_str()));if(!root){error="INVALID JSON";return false;}Project p;auto r=root.get();auto pats=item(r,"patterns");if(!cJSON_IsObject(pats)){error="INVALID PROJECT";return false;}p.patterns.clear();cJSON* po=nullptr;cJSON_ArrayForEach(po,pats){int id;try{id=std::stoi(po->string);}catch(...){return false;}if(id<0||id>127)return false;Pattern pat;pat.length=val(po,"length",64,1,128);pat.name=str(po,"name");auto cells=item(po,"cells");if(cJSON_GetArraySize(cells)<8)return false;for(int t=0;t<cJSON_GetArraySize(cells);t++){auto a=cJSON_GetArrayItem(cells,t);for(int s=0;s<std::min(128,cJSON_GetArraySize(a));s++){Cell c=readCell(cJSON_GetArrayItem(a,s));if(t>=tracks){if(!c.empty()){error="PROJECT USES TRACKS 9-24";return false;}}else pat.cells[t][s]=std::move(c);}}auto ins=item(po,"trackInstruments");for(int t=tracks;t<cJSON_GetArraySize(ins);t++){auto x=cJSON_GetArrayItem(ins,t);if(cJSON_IsNumber(x)&&x->valueint>=0){error="PROJECT USES TRACKS 9-24";return false;}}if(ins)readarr(ins,pat.instruments,-1,47);else readarr(item(r,"trackInstruments"),pat.instruments,-1,47);readarr(item(po,"trackVolumes"),pat.levels,0,120);for(int t=0;t<tracks;t++){readarr(cJSON_GetArrayItem(item(po,"sends"),t),pat.sends[t],0,100);readarr(cJSON_GetArrayItem(item(po,"trackEQ"),t),pat.eq[t],-18,18);}for(auto key:{"trackMutes","trackSolos"}){auto a=item(po,key);for(int i=0;i<cJSON_GetArraySize(a);i++){int t=cJSON_GetArrayItem(a,i)->valueint;if(t>=0&&t<tracks)(std::string(key)=="trackMutes"?pat.mute:pat.solo)|=1<<t;}}p.patterns[id]=std::move(pat);}
    if(p.patterns.empty())return false;p.selected=val(r,"selected",0,0,127);if(!p.patterns.count(p.selected))p.selected=p.patterns.begin()->first;auto bpm=item(r,"bpm");p.bpm=cJSON_IsNumber(bpm)?clamp(int(bpm->valuedouble*10),400,8000):1200;p.advance=val(r,"step",1,0,16);p.master=val(r,"master",100,0,120);auto song=item(r,"song");p.song.clear();for(int i=0;i<std::min(256,cJSON_GetArraySize(song));i++){int id=cJSON_GetArrayItem(song,i)->valueint;if(p.patterns.count(id))p.song.push_back(id);}if(p.song.empty())p.song={p.selected};auto sa=item(r,"slots");size_t memory=0;for(int i=0;i<std::min(slots,cJSON_GetArraySize(sa));i++){auto o=cJSON_GetArrayItem(sa,i);auto &s=p.instruments[i];s.name=str(o,"name","EMPTY");s.wave=val(o,"wave",0,0,9);s.root=val(o,"root",60,0,127);auto values=item(item(o,"omondeu"),"values");if(cJSON_GetArraySize(values)==23){for(int j=0;j<23;j++){int x=cJSON_GetArrayItem(values,j)->valueint;const int lo[]={0,0,0,0,0,-2,-24,0,30,0,0,0,2,10,0,5,0,0,0,-45,10,0,0};const int hi[]={3,3,100,100,100,0,24,40,16000,95,100,100,2000,3000,100,3000,2,1000,100,45,3000,100,100};s.patch[j]=clamp(x,lo[j],hi[j]);}}auto pcm=str(o,"pcm");if(!pcm.empty()){if(!decode(pcm,s.pcm))return false;memory+=s.pcm.size()*4;if(memory>32000000){error="POCKET SAMPLE LIMIT 32 MB";return false;}auto sr=item(o,"sampleRate");s.sampleRate=sr?std::clamp(sr->valuedouble,8000.0,192000.0):rate;auto q=item(o,"playback");s.mode=val(q,"mode",0,0,5);s.start=val(q,"start",0,0,s.pcm.size()-1);s.end=val(q,"end",s.pcm.size(),s.start+1,s.pcm.size());s.position=val(q,"position",500,0,1000);s.length=val(q,"grainLength",120,1,1000);s.shape=val(q,"shape",3,0,3);s.direction=val(q,"direction",0,0,2);s.spread=val(q,"spread",8,0,100);s.octave=val(q,"octave",0,-3,3);auto slices=item(q,"slices");for(int j=0;j<std::min(48,cJSON_GetArraySize(slices));j++)s.slices.push_back(clamp(cJSON_GetArrayItem(slices,j)->valueint,s.start,s.end-1));auto a=item(q,"positionAutomation");s.lfoMode=val(a,"mode",0,0,2);s.lfoShape=val(a,"shape",0,0,5);s.lfoSpeed=val(a,"speed",0,0,28);s.lfoFree=val(a,"freeRate",25,5,2000);s.lfoDepth=val(a,"depth",100,0,100);s.scanMode=val(a,"scanMode",0,0,2);readarr(item(a,"anchors"),s.anchors,0,1000);}}auto fx=item(r,"fxSettings");const char* keys[]={"size","decay","predelay","damping","width","reverbLevel","division","feedback","delayDamping","delayLevel"};const int hi[]={100,120,250,100,150,100,6,90,100,100};for(int i=0;i<10;i++)p.fx[i]=val(fx,keys[i],p.fx[i],i==1?1:0,hi[i]);p.fx[10]=cJSON_IsFalse(item(fx,"pingpong"))?0:1;tm_play(0);for(auto &[id,old]:project.patterns)for(int t=0;t<tracks;t++)for(int s=0;s<steps;s++)tm_cell_at4(id,t,s,0,-1,100,100,0,0,0,0,0,0,0);project=std::move(p);publishAll();return true;}

// Dedicated SDL callback uses the unchanged Termin DSP, interleaved output.
void audio(void*,Uint8* stream,int bytes){auto *out=reinterpret_cast<float*>(stream);int frames=bytes/(2*sizeof(float));std::array<float,512> l,r;for(int off=0;off<frames;off+=512){int n=std::min(512,frames-off);tm_render(l.data(),r.data(),n);for(int i=0;i<n;i++){out[(off+i)*2]=l[i];out[(off+i)*2+1]=r[i];}}}
#include "PocketWav.h"
bool importWav(const fs::path& path,int slot,std::string& message){
    if(slot<10||slot>=slots){message="INVALID SAMPLE SLOT";return false;}
    Slot s;if(!decodeWav(path,s,message))return false;
    size_t used=0;for(int i=0;i<slots;i++)if(i!=slot)used+=project.instruments[i].pcm.size()*4;
    if(used+s.pcm.size()*4>32000000){message="SAMPLE MEMORY FULL";return false;}
    if(!tm_instrument_sample(slot,s.pcm.data(),s.pcm.size(),s.sampleRate,s.root)){message="AUDIO ENGINE REJECTED WAV";return false;}
    project.instruments[slot]=std::move(s);++sampleRevision[slot];tm_instrument_wave(slot,2);publishSampleConfig(slot);return true;
}

