constexpr uint32_t black=0x000000,panel=0x131313,beat=0x222121,line=0x515151,green=0x546d54,cyan=0x598e8e,olive=0x6c7448,white=0xc0c0c0,recCol=0x895d58,selection=0x202a1f;
SDL_Renderer* renderer=nullptr;SDL_Texture* font=nullptr;
