void initFont(){SDL_Surface* s=SDL_CreateRGBSurfaceWithFormat(0,16*6,8*8,32,SDL_PIXELFORMAT_RGBA32);SDL_FillRect(s,nullptr,0);for(auto &[ch,g]:glyphs){unsigned u=ch;for(int y=0;y<7;y++)for(int x=0;x<5;x++)if(g[y]&(1<<(4-x))){SDL_Rect r{int(u%16)*6+x,int(u/16)*8+y,1,1};SDL_FillRect(s,&r,SDL_MapRGBA(s->format,255,255,255,255));}}font=SDL_CreateTextureFromSurface(renderer,s);SDL_SetTextureBlendMode(font,SDL_BLENDMODE_BLEND);SDL_FreeSurface(s);}
