enum Button{UP,DOWN,LEFT,RIGHT,A,B,X,Y,L1,R1,L2,R2,START,SELECT,MENU,BUTTON_COUNT};int page=PATTERN,track=0,row=0,field=0,scroll=0,focus=0,octave=4,songRow=0,saveSlot=1;bool running=false,songPlay=false,rec=false,shift=false,detail=false,quit=false,dirty=false;int modal=0,menu=0,editNote=60,chord=0,fillRole=0,fillPreset=0;std::string message="A EDIT  /  SELECT PAGES";struct UndoStep{int pattern,track,row;Cell value;};std::vector<UndoStep> undo;Cell clipboard;std::vector<fs::path> wavs;int waveIndex=0;fs::path dataRoot=".";std::mt19937 rng(std::random_device{}());
