void commitNote(){int i=assigned();if(i<0){message="NO INSTRUMENT";modal=0;return;}checkpoint();cell().notes.clear();for(int n:chordIntervals[chord])cell().notes.push_back(clamp(editNote+n,0,127));cell().off=false;cell().instrument=-1;change();preview();row=std::min(pat().length-1,row+project.advance);modal=0;}
void adjustCell(int d){if(!rec){message="L2+A ENABLE REC";return;}checkpoint();if(field==0){if(cell().notes.empty()){modal=2;editNote=(octave+1)*12;}else{for(int &n:cell().notes)n=clamp(n+d,0,127);change();preview();}}else if(field==1){int i=clamp(assigned()+d,0,47);if(project.instruments[i].name!="EMPTY"){assignTrack(i);}}else if(field==2){cell().velocity=clamp(cell().velocity+d,0,100);change();}else if(field==3){cell().volume=clamp(cell().volume+d,0,100);change();}else if(field==4){cell().pan=clamp(cell().pan+d,-50,50);change();}else if(field==5){cell().fx=clamp(cell().fx+d,0,8);change();}else if(field==6){cell().fxv=clamp(cell().fxv+d,0,100);change();}else{cell().micro=clamp(cell().micro+d*25,0,75);change();}}
void fill(){int i=pat().instruments[track];if(i<0){i=fillRole==0?0:fillRole==1?8:fillRole==2?1:9;pat().instruments[track]=i;}for(int r=0;r<pat().length;r++){auto &c=pat().cells[track][r];c=Cell{};int b=r%16;bool hit=false;if(fillPreset==2)hit=rng()%100<(fillRole==2?65:28);else if(fillRole==0)hit=fillPreset==0?b%4==0:(b==0||b==6||b==10);else if(fillRole==1)hit=b==4||b==12||(fillPreset==1&&b==11);else if(fillRole==2)hit=fillPreset==0?b%2==0:b%4!=0;else hit=fillPreset==0?b%4==0:(b==0||b==3||b==7||b==10||b==14);if(hit){int n=fillRole<3?(project.instruments[i].pcm.empty()?(fillRole==0?36:fillRole==1?50:66):project.instruments[i].root):36+std::array<int,5>{0,3,5,7,10}[rng()%5];c.notes={n};if(fillRole==5)c.notes={n,n+3,n+7,n+10};c.instrument=-1;c.velocity=fillRole==2?45+rng()%45:75+rng()%25;c.volume=85;c.pan=fillRole==2?int(rng()%31)-15:0;c.micro=(b%2)*12+rng()%8;if(fillRole>=3){c.duration=fillRole==5?16:4+rng()%9;}if(fillRole==2&&rng()%5==0){c.fx=2;c.fxv=20;}else if(rng()%4==0){c.fx=4;c.fxv=20+rng()%30;}else if(rng()%5==0){c.fx=5;c.fxv=25+rng()%20;}}publishCell(project.selected,track,r);}dirty=true;message="FILL APPLIED";modal=0;}
