void drawGrid(){int visible=detail?2:4,first=(track/visible)*visible,w=(640-28)/visible,play=running?tm_step():-1;if(songPlay&&running){int p=tm_playing_pattern();if(p>=0&&project.patterns.count(p)&&p!=project.selected){project.selected=p;row=0;scroll=0;}}if(running&&play>=0){if(play<scroll)scroll=play;if(play>=scroll+19)scroll=play-18;}else{if(row<scroll)scroll=row;if(row>=scroll+19)scroll=row-18;}scroll=clamp(scroll,0,std::max(0,pat().length-19));for(int j=0;j<visible;j++){int t=first+j,x=28+j*w;box(x,34,w-1,32,panel);text(x+4,38,num(t+1)+" "+(pat().instruments[t]>=0?project.instruments[pat().instruments[t]].name:"EMPTY"),t==track?cyan:white,1,w/6-1);text(x+4,53,detail?"NOTE INS VEL VOL PAN FX  VAL TIM":"NOTE INS VEL FX",olive,1,w/6-1);}for(int r=scroll;r<std::min(pat().length,scroll+19);r++){int y=66+(r-scroll)*19;box(0,y,640,19,r==play?selection:r%4==0?beat:black);text(2,y+5,num(r+1),line,1);for(int j=0;j<visible;j++){int t=first+j,x=28+j*w;auto &c=pat().cells[t][r];if(row==r&&t==track){box(x,y,w-2,19,selection);border(x,y,w-2,19,rec?recCol:green);}std::string n=c.off?"OFF":c.notes.empty()?"---":noteName(c.notes.front())+(c.notes.size()>1?"+":"");bool held=false;if(c.notes.empty()&&!c.off){for(int s=r-1;s>=0;s--){auto &a=pat().cells[t][s];if(a.off)break;if(!a.notes.empty()){if(a.duration>(r-s)*4){n=noteName(a.notes.front())+(a.notes.size()>1?"+":"");held=true;}break;}}}int ins=c.instrument>=0?c.instrument:pat().instruments[t];text(x+3,y+3,n,held?line:white,2,4);if(detail){const std::string vs[]={c.empty()?"--":num(ins+1),c.empty()?"--":num(c.velocity),num(c.volume),std::to_string(c.pan),std::string(effects[c.fx]).substr(0,2),num(c.fxv),num(c.micro)};for(int k=0;k<7;k++)text(x+56+k*34,y+6,vs[k],k<3?olive:k==3?green:cyan,1,5);if(row==r&&t==track)border(x+(field==0?0:53+(field-1)*34),y,field==0?53:34,19,white);}else{text(x+56,y+5,c.empty()?"--":num(ins+1),olive,1);text(x+82,y+5,c.empty()?"--":num(c.velocity),olive,1);text(x+112,y+5,c.fx?std::string(effects[c.fx]).substr(0,2):"--",cyan,1);if(row==r&&t==track){int col=field==0?0:field==1?52:field==2?78:108;border(x+col,y,field==0?51:26,19,white);}}}}}
void list(const std::vector<std::pair<std::string,std::string>>& rows,int selected){int start=std::max(0,std::min(int(rows.size())-16,selected-7));for(int i=start;i<std::min(int(rows.size()),start+16);i++){int y=52+(i-start)*23;box(18,y,604,21,i==selected?selection:panel);if(i==selected)border(18,y,604,21,green);text(28,y+4,rows[i].first,white,2,34);text(432,y+4,rows[i].second,i==selected?cyan:olive,2,15);}}
void drawPage(){if(modal==6){drawBrowser();SDL_RenderPresent(renderer);return;}header();if(page==PATTERN)drawGrid();else if(page==SONG){std::vector<std::pair<std::string,std::string>> a;for(int i=0;i<(int)project.song.size();i++)a.push_back({num(i+1)+"  PATTERN "+num(project.song[i]),std::to_string(project.patterns[project.song[i]].length)+" STEPS"});list(a,songRow);}else if(page==INSTRUMENT){drawInstrumentPage();}else if(page==OMONDEU){int i=trackSlot();if(i<0||project.instruments[i].wave!=9||hasSample(i)){center(0,200,640,"A ASSIGN OMONDEU",cyan);}else{std::vector<std::pair<std::string,std::string>> a;for(int k=0;k<23;k++)a.push_back({omLabels[k],std::to_string(project.instruments[i].patch[k])});list(a,focus);}}else if(page==SAMPLER||page==GRANULAR){drawSamplePage(page==GRANULAR);}else if(page==MIXER){for(int t=0;t<tracks;t++){int x=8+t*79;box(x,55,74,362,panel);border(x,55,74,362,t==track?cyan:line);center(x,66,74,"T"+num(t+1));int h=clamp(int(tm_meter_level(t+0)*310),0,260);box(x+10,110,16,250,beat);box(x+10,360-h,16,h,green);box(x+43,115,3,240,line);box(x+34,355-pat().levels[t]*2,22,10,white);center(x,378,74,std::to_string(pat().levels[t]),olive);center(x,397,74,(pat().mute&(1<<t))?"MUTE":(pat().solo&(1<<t))?"SOLO":"",recCol,1);}message="A MUTE X SOLO Y SENDS UP/DOWN LEVEL";}else if(page==FX){drawFXPage();}else if(page==PROJECT){center(0,95,640,"PROJECT SLOT "+num(saveSlot),cyan);center(0,150,640,"UP / DOWN  SLOT");center(0,190,640,"A SAVE   Y LOAD");center(0,230,640,"X EXIT");center(0,295,640,"DSP "+std::to_string(tm_dsp_load()/10)+"%  PEAK "+std::to_string(tm_dsp_peak()/10)+"%",olive);center(0,320,640,"OVERRUNS "+std::to_string(tm_dsp_overruns()),white);}
    footer();if(modal){box(92,75,456,330,panel);border(92,75,456,330,cyan);if(modal==1){center(92,88,456,"SELECT PAGE",cyan);for(int i=0;i<PAGE_COUNT;i++){box(112,115+i*30,416,27,menu==i?selection:beat);center(112,121+i*30,416,pageNames[i]);}}else if(modal==2){center(92,100,456,"NOTE / CHORD",cyan);center(92,160,456,noteName(editNote)+"  "+chordNames[chord],white,3);center(92,230,456,"UP/DOWN PITCH  L1/R1 OCT",olive,1);center(92,258,456,"LEFT/RIGHT CHORD  Y PREVIEW",olive,1);center(92,300,456,"A APPLY   B CANCEL");}else if(modal==3){center(92,88,456,"PATTERN ACTIONS",cyan);for(int i=0;i<11;i++){box(112,112+i*24,416,22,menu==i?selection:beat);center(112,116+i*24,416,contextItems[i]);}}else if(modal==4){center(92,100,456,"CREATIVE FILL",cyan);center(92,160,456,std::array<std::string,6>{"KICK","SNARE","HIHAT","BASS","LEAD","CHORDS"}[fillRole]);center(92,198,456,std::array<std::string,3>{"STANDARD","SYNCOPATED","RANDOM"}[fillPreset],olive);center(92,275,456,"UP/DOWN ROLE  LEFT/RIGHT STYLE",white,1);center(92,310,456,"A APPLY  B CANCEL");}else if(modal==5){center(92,100,456,contextItems[menu],cyan);int v=menu==1?cell().duration:menu==3?pat().length:menu==5?project.bpm/10:menu==6?project.advance:menu==8?cell().fx2:cell().fxv2;center(92,165,456,menu==1?std::to_string(v/4)+"."+num(v%4*25)+" STEPS":menu==8?effects[v]:std::to_string(v),white,3);center(92,265,456,"ARROWS CHANGE   A DONE");}else if(modal==7){center(92,155,456,"EXIT TERMIN POCKET?");center(92,205,456,"SAVE PROJECT FIRST",olive);center(92,260,456,"A EXIT  B CANCEL");}}
    SDL_RenderPresent(renderer);}
Button key(SDL_Keycode k){switch(k){case SDLK_UP:return UP;case SDLK_DOWN:return DOWN;case SDLK_LEFT:return LEFT;case SDLK_RIGHT:return RIGHT;case SDLK_z:return B;case SDLK_x:return A;case SDLK_s:return X;case SDLK_a:return Y;case SDLK_q:return L1;case SDLK_r:return R1;case SDLK_w:return L2;case SDLK_e:return R2;case SDLK_SPACE:return START;case SDLK_TAB:return SELECT;default:return Button(-1);}}
Button button(Uint8 b){switch(b){case SDL_CONTROLLER_BUTTON_DPAD_UP:return UP;case SDL_CONTROLLER_BUTTON_DPAD_DOWN:return DOWN;case SDL_CONTROLLER_BUTTON_DPAD_LEFT:return LEFT;case SDL_CONTROLLER_BUTTON_DPAD_RIGHT:return RIGHT;case SDL_CONTROLLER_BUTTON_A:return A;case SDL_CONTROLLER_BUTTON_B:return B;case SDL_CONTROLLER_BUTTON_X:return X;case SDL_CONTROLLER_BUTTON_Y:return Y;case SDL_CONTROLLER_BUTTON_LEFTSHOULDER:return L1;case SDL_CONTROLLER_BUTTON_RIGHTSHOULDER:return R1;case SDL_CONTROLLER_BUTTON_START:return START;case SDL_CONTROLLER_BUTTON_BACK:return SELECT;default:return Button(-1);}}
void demo(){auto &p=pat();p.instruments={0,8,1,9,3,-1,-1,-1};for(int r=0;r<64;r++){if(r%4==0)p.cells[0][r].notes={36};if(r%16==4||r%16==12)p.cells[1][r].notes={50};if(r%2==0){p.cells[2][r].notes={66};p.cells[2][r].velocity=r%4==0?82:52;}if(r%8==0){p.cells[3][r].notes={r<32?41:37};p.cells[3][r].duration=20;}if(r%16==0){p.cells[4][r].notes={53,56,60,63};p.cells[4][r].duration=60;}}publishAll();}
#include "PocketStartup.h"
#include "PocketTests.h"

int main(int argc,char**argv){
    bool screenshot=argc>2&&std::string(argv[1])=="--preview";
    bool homeScreenshot=argc>2&&std::string(argv[1])=="--preview-home";
    bool exportDemo=argc>2&&std::string(argv[1])=="--demo-project";
    if(exportDemo){tm_init(rate);demo();return save(argv[2])?0:1;}
    dataRoot=argc>1&&std::string(argv[1])!="--self-test"?fs::path(argv[1]):fs::current_path();
    if(argc>1&&std::string(argv[1])=="--self-test"){
        tm_init(rate);demo();tm_play(1);std::vector<float> l(256),r(256);double energy=0;
        for(int j=0;j<500;j++){tm_render(l.data(),r.data(),256);for(float x:l){if(!std::isfinite(x))return 2;energy+=x*x;}}
        tm_play(0);if(energy<=0)return 3;auto p=fs::temp_directory_path()/"termin-pocket-test.trackermac";if(!save(p))return 4;std::string e;
        if(!load(p,e)){std::cerr<<e;return 5;}fs::remove(p);if(project.patterns[0].cells[0][0].notes!=std::vector<int>{36})return 6;
        bootPage=BootPage::Home;homeChoice=0;input(A,true);if(bootPage!=BootPage::Editor||!cell().notes.empty()||assigned()!=-1)return 7;
        input(L2,true);input(A,true);input(A,false);input(L2,false);if(!rec||modal!=0)return 8;
        input(R2,true);if(modal!=3)return 9;input(R2,true);if(modal!=0)return 10;
        input(SELECT,true);if(modal!=1)return 11;input(B,true);if(modal!=0)return 12;
        input(MENU,true);if(bootPage!=BootPage::Home)return 13;
        homeChoice=2;input(A,true);if(bootPage!=BootPage::Editor||cell().notes!=std::vector<int>{36})return 14;
        std::cout<<"Pocket 8-track engine, roundtrip, NEW/DEMO and editor shortcuts passed\n";
        if(argc>2&&(!regressionTests(argv[2])||!uiSmokeTest()||!fxSignalTest()))return 15;return 0;
    }
    handheld=std::getenv("TERMIN_POCKET_HANDHELD")!=nullptr;
    if(SDL_Init(SDL_INIT_VIDEO|SDL_INIT_AUDIO|SDL_INIT_GAMECONTROLLER|SDL_INIT_JOYSTICK)<0){std::cerr<<SDL_GetError();return 1;}
    SDL_Window* window=SDL_CreateWindow("TERMIN TRACKER POCKET",SDL_WINDOWPOS_CENTERED,SDL_WINDOWPOS_CENTERED,640,480,SDL_WINDOW_SHOWN|(handheld?SDL_WINDOW_FULLSCREEN_DESKTOP:0));
    if(!window){std::cerr<<SDL_GetError();return 2;}
    renderer=SDL_CreateRenderer(window,-1,SDL_RENDERER_ACCELERATED|SDL_RENDERER_PRESENTVSYNC);if(!renderer)renderer=SDL_CreateRenderer(window,-1,SDL_RENDERER_SOFTWARE);if(!renderer)return 3;
    SDL_RenderSetLogicalSize(renderer,640,480);SDL_ShowCursor(SDL_DISABLE);initFont();tm_init(rate);
    if(screenshot||homeScreenshot){if(screenshot){demo();track=3;row=1;drawPage();}else{bootPage=BootPage::Home;drawStartup();}SDL_Surface* pixels=SDL_CreateRGBSurfaceWithFormat(0,640,480,32,SDL_PIXELFORMAT_RGBA32);SDL_RenderReadPixels(renderer,nullptr,SDL_PIXELFORMAT_RGBA32,pixels->pixels,pixels->pitch);int result=SDL_SaveBMP(pixels,argv[2]);SDL_FreeSurface(pixels);SDL_Quit();return result!=0;}
    SDL_AudioSpec wanted{},got{};wanted.freq=rate;wanted.format=AUDIO_F32SYS;wanted.channels=2;wanted.samples=512;wanted.callback=audio;
    auto dev=SDL_OpenAudioDevice(nullptr,0,&wanted,&got,0);publishAll();if(dev)SDL_PauseAudioDevice(dev,0);else std::cerr<<"AUDIO DEVICE FAILED: "<<SDL_GetError()<<std::endl;
    if(handheld)openPhysicalPad();
    std::vector<SDL_GameController*> pads;if(!physicalPad)for(int i=0;i<SDL_NumJoysticks();i++)if(SDL_IsGameController(i))pads.push_back(SDL_GameControllerOpen(i));
    bool l2=false,r2=false;bootAt=SDL_GetTicks();
    while(!quit){
        SDL_Event e;while(SDL_PollEvent(&e)){
            if(e.type==SDL_QUIT)quit=true;
            if(e.type==SDL_KEYDOWN||e.type==SDL_KEYUP){if(e.type==SDL_KEYDOWN&&e.key.repeat&&(e.key.keysym.sym==SDLK_x||e.key.keysym.sym==SDLK_e||e.key.keysym.sym==SDLK_TAB))continue;Button b=key(e.key.keysym.sym);if(int(b)>=0)input(b,e.type==SDL_KEYDOWN);else if(e.type==SDL_KEYDOWN&&e.key.keysym.sym==SDLK_ESCAPE){if(bootPage==BootPage::Editor)input(MENU,true);else if(bootPage==BootPage::Home)quit=true;else input(B,true);}}
            // Raw handheld input is handled exclusively by pollPhysical: do not
            // also dispatch remapped Controller events for the same presses.
            if(!physicalPad){
                if(e.type==SDL_CONTROLLERBUTTONDOWN||e.type==SDL_CONTROLLERBUTTONUP){Button b=button(e.cbutton.button);if(e.cbutton.button==SDL_CONTROLLER_BUTTON_GUIDE)b=MENU;if(int(b)>=0)input(b,e.type==SDL_CONTROLLERBUTTONDOWN);}
                if(e.type==SDL_CONTROLLERAXISMOTION){if(e.caxis.axis==SDL_CONTROLLER_AXIS_TRIGGERLEFT){bool on=e.caxis.value>16000;if(on!=l2){l2=on;input(L2,on);}}if(e.caxis.axis==SDL_CONTROLLER_AXIS_TRIGGERRIGHT){bool on=e.caxis.value>16000;if(on!=r2){r2=on;input(R2,on);}}}
                if(e.type==SDL_CONTROLLERDEVICEADDED&&SDL_IsGameController(e.cdevice.which))pads.push_back(SDL_GameControllerOpen(e.cdevice.which));
            }
        }
        pollPhysical();color(black);SDL_RenderClear(renderer);if(bootPage==BootPage::Editor)drawPage();else drawStartup();SDL_Delay(15);
    }
    tm_play(0);if(dev)SDL_CloseAudioDevice(dev);if(physicalPad)SDL_JoystickClose(physicalPad);for(auto p:pads)if(p)SDL_GameControllerClose(p);SDL_DestroyTexture(font);SDL_DestroyRenderer(renderer);SDL_DestroyWindow(window);SDL_Quit();return 0;
}
